// ─────────────────────────────────────────────────────────────────────────
// 프롬프트 렌더링 — 4단계
// 실행 모드: Run Once for Each Item
//
// 3단계와 달리 게이트가 없다. 조회가 이미 걸렀다 —
// subject 가 있고 body 가 있는 기사만 온다.
//
// 본문은 전문을 보낸다. 상한을 두지 않는 이유는 docs/4_analyze.md 에 있다:
// 긴 본문이 실제로 문제인지 아직 모르고, 지금 상한을 두면 첫 실험을
// 해석할 수 없다(원문이 길어 흐려진 건지, 잘려서 핵심이 사라진 건지).
// ─────────────────────────────────────────────────────────────────────────

const P = $('GET prompt').first().json;

const VALUES = {
  SUBJECT_NAME: $json.subject_name ?? '',
  PRESS: $json.press ?? '',
  PUBLISHED_AT: $json.published_at ?? '',
  TITLE: $json.title ?? '',
  BODY: $json.body ?? '',
};
const TOKEN = /\[\[([A-Z_]+)\]\]/g;

// 렌더링 **전에** 필수 토큰이 정확히 한 번씩 있는지 검증한다
const counts = {};
for (const t of P.user_template.matchAll(TOKEN)) {
  counts[t[1]] = (counts[t[1]] || 0) + 1;
}
for (const k of Object.keys(VALUES)) {
  if (counts[k] !== 1) {
    throw new Error(`user_template 의 [[${k}]] 가 ${counts[k] || 0}번 — 정확히 1번이어야 한다`);
  }
}
const unknown = Object.keys(counts).filter((k) => !(k in VALUES));
if (unknown.length) {
  throw new Error(`user_template 에 모르는 자리표시자: ${unknown.join(', ')}`);
}

// 한 번의 정규식 치환으로 처리한다. 순차 치환하면 본문에 다른
// 자리표시자 문자열이 들어 있을 때 재치환된다.
const userPrompt = P.user_template.replace(TOKEN, (whole, key) =>
  key in VALUES ? VALUES[key] : whole);

return {
  json: {
    article_id: $json.id,
    subject_id: $json.subject_id,
    subject_name: $json.subject_name,
    press: $json.press,
    title: $json.title,
    body_chars: $json.body_chars,        // 요약이 본문 길이 대 summary 길이를 잰다
    prompt_version: P.version,
    prompt_sha256: P.sha256,
    system_prompt: P.system_prompt,
    user_prompt: userPrompt,
  },
};

// ─────────────────────────────────────────────────────────────────────────
// 분석 출력 검증 — LLM 응답을 POST /articles/analyze 요청 본문으로
// 실행 모드: Run Once for Each Item
//
// 형식 검증만 한다. issue_signal 30자 상한과 summary 400자 경고는
// collector 가 tuning.yaml 을 보고 판단한다 — 여기 숫자를 쓰면
// 값이 사는 곳이 하나 더 생긴다.
// ─────────────────────────────────────────────────────────────────────────

const src = $('렌더링').item.json;

const base = {
  article_id: src.article_id,
  subject_id: src.subject_id,
  prompt_version: src.prompt_version,
  _press: src.press,
  _title: src.title,
  _body_chars: src.body_chars,
};

// 에이전트 에러 아이템 (onError: continueRegularOutput)
if ($json.error !== undefined) {
  const e = $json.error;
  return { json: { ...base, state: 'failed',
    error: String((e && (e.message || e.description)) || e).slice(0, 300),
    model: 'gpt-5.6-luna' }};
}

const out = $json.output ?? $json;

function fail(reject, detail) {
  return { json: { ...base, __skip: true, reject, detail: String(detail).slice(0, 120) }};
}

if (out === null || typeof out !== 'object') return fail('not_an_object', typeof out);

const summary = typeof out.summary === 'string' ? out.summary.trim() : '';
if (!summary) return fail('empty_summary', JSON.stringify(out).slice(0, 80));

const ct = out.change_type;
if (ct !== '변화' && ct !== '해설' && ct !== '동향') {
  return fail('bad_change_type', ct);
}

// null 은 무이슈라는 **정상 출력**이다. 현재 사건에 연결되지 않는 evergreen
// 기사에 이슈를 강제하면 가짜 해설 클러스터가 생긴다. 빈 문자열은 형식
// 실패라 구분한다 — 섞어 세면 프롬프트 튜닝 신호가 오염된다.
let signal = out.issue_signal;
if (signal === undefined) return fail('missing_issue_signal', '');
if (signal !== null) {
  if (typeof signal !== 'string') return fail('signal_not_string', typeof signal);
  signal = signal.trim();
  if (!signal) return fail('signal_empty_string', '');
}

return { json: { ...base,
  state: 'done',
  summary,
  issue_signal: signal,
  change_type: ct,
  model: 'gpt-5.6-luna',
}};

// ─────────────────────────────────────────────────────────────────────────
// 분석 요약 — 상위 워크플로가 완료를 읽는 단일 지점
// 실행 모드: Run Once for All Items
//
// 첫 실행에서 볼 것(docs/4_analyze.md):
//   긴 본문일수록 summary_warn 이 늘어나는가
//   긴 본문에서 issue_signal 이 넓거나 모호해지는가
// 그래서 건별 관측값을 samples 에 남긴다 — 이게 본문 상한을 둘지의 재료다.
// ─────────────────────────────────────────────────────────────────────────

const items = $input.all().map(i => i.json || {});
const zero = items.find(j => j.__zero_pending === true);
const rows = items.filter(j => !j.__zero_pending);

let pending = 0;
try { pending = $('GET pending').first().json.count || 0; }
catch (e) { pending = zero ? 0 : rows.length; }

const saved    = rows.filter(r => r.result === 'inserted' || r.result === 'already_exists');
const skipped  = rows.filter(r => r.__skip === true);
const rejected = rows.filter(r => r.detail && r.detail.error);

const tallyBy = (arr, key) => {
  const t = {};
  for (const r of arr) { const k = r[key] || 'unknown'; t[k] = (t[k] || 0) + 1; }
  return t;
};

// 관측 샘플 — 본문 길이와 압축 결과를 짝지어 남긴다
const samples = [];
try {
  for (const it of $('출력 검증').all()) {
    const j = it.json;
    samples.push({
      press: j._press,
      body_chars: j._body_chars,
      title: String(j._title || '').slice(0, 40),
      state: j.state || (j.__skip ? 'skipped' : null),
      issue_signal: j.issue_signal ?? null,
      summary_chars: j.summary ? j.summary.length : 0,
    });
  }
} catch (e) {}

// collector 응답에서 signal 거절·summary 경고를 가져온다.
// 30자 상한과 400자 경고는 tuning.yaml 이 정본이라 여기서 다시 세지 않는다.
// no_signal 은 collector 가 판정해서 응답에 담는다 —
// state=done 이고 signal 이 없고 거절도 아닐 때만 true.
// 여기서 issue_signal===null 을 세면 **분석 실패까지 무이슈로 집계된다.**
// 원인이 다른 것을 같은 신호로 만들지 않는다.
const signalRejected = saved.filter(r => r.signal_rejected).length;
const summaryWarn    = saved.filter(r => (r.warnings || []).length > 0).length;
const noSignal       = saved.filter(r => r.no_signal === true).length;
const failed         = saved.filter(r => r.state === 'failed').length;
// 재시도가 몇 건 돌았는지. 실패 행은 UPDATE 되므로 attempts 가 오른다
const retried        = saved.filter(r => r.result === 'retried').length;

return [{
  json: {
    stage: 'analyze',
    ok: rejected.length === 0 && skipped.length === 0 && failed === 0,
    pending_articles: pending,
    processed: rows.length,
    inserted:       saved.filter(r => r.result === 'inserted').length,
    already_exists: saved.filter(r => r.result === 'already_exists').length,
    retried,
    failed,
    // 관측 — 원인이 다른 것을 같은 신호로 만들지 않는다
    no_signal: noSignal,            // 무이슈. 정상 출력이다
    signal_rejected: signalRejected, // 30자 초과 등 검증 거절
    summary_warn: summaryWarn,       // 400자 초과. 경고만
    format_rejected: skipped.length,
    collector_rejected: rejected.length,
    format_reasons:    tallyBy(skipped, 'reject'),
    collector_reasons: rejected.map(r => r.detail.error)
      .reduce((t, k) => (t[k] = (t[k] || 0) + 1, t), {}),
    samples,
    finished_at: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
  },
}];
